-- Real campsites from Recreation.gov (RIDB), generated 2026-11-17. Run AddRecreationGovSites.sql first.
-- Safe to re-run. Regenerate it with the scripts in RecreationGov/ (see the README there) rather than editing it by hand.
--
-- For each campground found on Recreation.gov, this:
--   1. records its Recreation.gov facility id,
--   2. deletes the placeholder sites from CreateSiteTable.sql, or retires the ones reservations still point at,
--   3. adds or updates the real sites. Prices follow the placeholder rules: the campground's rate, +$10 for RV and
--      electric sites, and double for group sites, cabins and yurts. Recreation.gov's own prices aren't in RIDB.
SET NOCOUNT ON;
-- Writing to dbo.Site, which has filtered indexes, needs this; sqlcmd turns it off by default.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;

CREATE TABLE #RecGovSite
(
    ParkName       NVARCHAR(100) NOT NULL,
    CampgroundName NVARCHAR(100) NOT NULL,
    FacilityId     INT           NOT NULL,
    CampsiteId     INT           NOT NULL PRIMARY KEY,
    SiteNumber     NVARCHAR(30)  NOT NULL,
    Loop           NVARCHAR(50)  NULL,
    SiteType       NVARCHAR(20)  NOT NULL,
    MaxGuests      INT           NULL,
    RateMultiplier INT           NOT NULL,
    RateExtra      INT           NOT NULL
);

