BEGIN TRANSACTION;

DECLARE @Imported TABLE (CampgroundId INT PRIMARY KEY, FacilityId INT NOT NULL);
INSERT INTO @Imported (CampgroundId, FacilityId)
SELECT DISTINCT c.CampgroundId, r.FacilityId
FROM #RecGovSite r
JOIN dbo.Park p ON p.ParkName = r.ParkName
JOIN dbo.Campground c ON c.ParkId = p.ParkId AND c.CampgroundName = r.CampgroundName;

UPDATE c SET RecreationGovId = i.FacilityId
FROM dbo.Campground c JOIN @Imported i ON i.CampgroundId = c.CampgroundId;

-- Placeholder sites: delete the ones nobody booked, retire the rest so old trips still show their site.
DELETE s
FROM dbo.Site s JOIN @Imported i ON i.CampgroundId = s.CampgroundId
WHERE s.RecreationGovId IS NULL
  AND NOT EXISTS (SELECT 1 FROM dbo.Reservation res WHERE res.SiteId = s.SiteId);

UPDATE s SET Retired = 1
FROM dbo.Site s JOIN @Imported i ON i.CampgroundId = s.CampgroundId
WHERE s.RecreationGovId IS NULL;

MERGE dbo.Site AS target
USING (
    SELECT c.CampgroundId, r.CampsiteId, r.SiteNumber, r.Loop, r.SiteType,
           COALESCE(r.MaxGuests, c.MaxGuests) AS MaxGuests,
           c.NightlyRate * r.RateMultiplier + r.RateExtra AS NightlyRate
    FROM #RecGovSite r
    JOIN dbo.Park p ON p.ParkName = r.ParkName
    JOIN dbo.Campground c ON c.ParkId = p.ParkId AND c.CampgroundName = r.CampgroundName
) AS source
ON target.RecreationGovId = source.CampsiteId
WHEN MATCHED THEN
    UPDATE SET SiteNumber = source.SiteNumber, Loop = source.Loop, SiteType = source.SiteType,
               MaxGuests = source.MaxGuests, NightlyRate = source.NightlyRate, Retired = 0
WHEN NOT MATCHED BY TARGET THEN
    INSERT (CampgroundId, SiteNumber, Loop, SiteType, MaxGuests, NightlyRate, RecreationGovId)
    VALUES (source.CampgroundId, source.SiteNumber, source.Loop, source.SiteType, source.MaxGuests, source.NightlyRate,
            source.CampsiteId);

COMMIT;

DROP TABLE #RecGovSite;
